<script lang="ts">
 import {enhance} from '$app/forms';import {onMount,untrack} from 'svelte';import type {JobPolicy} from '$lib/server/job-settings';
 let {data,form}:{data:{policy:JobPolicy;settings:{version:string};basePath:string;choices:import('$lib/jobs').JobsPage['choices']};form?:{message?:string;failed?:boolean}|null}=$props();
 let policy=$state<JobPolicy>(untrack(()=>structuredClone(data.policy)));let trade=$state(untrack(()=>data.policy.enabledTrades[0]||'general'));let fieldLabel=$state('');let ready=$state(false);onMount(()=>{ready=true;});
 function customize(){policy.profiles[trade]={version:'1',fields:{},requiredFields:[],requiredSkills:[],tasks:[{title:'Confirm customer and site access',stage:'schedule',required:true,evidenceRequired:false}],completionPhotos:0,customerAcceptanceRequired:true,allowQualifiedAcceptance:false,stateLabels:{}};}
</script>
<section class="settings mx-auto max-w-3xl space-y-5 p-5"><a href={data.basePath}>← Jobs</a><h1>Job rules & trade profiles</h1>{#if form?.message}<p role={form.failed?'alert':'status'}>{form.message}</p>{/if}<form method="POST" action="?/save" use:enhance class="space-y-5"><input type="hidden" name="version" value={data.settings.version}/><input type="hidden" name="policy" value={JSON.stringify(policy)}/><label class="check"><input type="checkbox" bind:checked={policy.allowManual}/>Allow manual service / warranty Jobs</label><fieldset><legend>Enabled trades</legend>{#each ['general','concrete','framing','land-clearing','doors-locks'] as key}<label class="check"><input type="checkbox" value={key} bind:group={policy.enabledTrades}/>{key}</label>{/each}</fieldset><label>Trade profile<select bind:value={trade}>{#each policy.enabledTrades as key}<option>{key}</option>{/each}</select></label>
 {#if policy.profiles[trade]}{@const profile=policy.profiles[trade]}<label>Profile version<input bind:value={profile.version}/></label><label>Required completion photos<input type="number" min="0" max="30" bind:value={profile.completionPhotos}/></label><label class="check"><input type="checkbox" bind:checked={profile.customerAcceptanceRequired}/>Require customer acceptance before close</label><label class="check"><input type="checkbox" bind:checked={profile.allowQualifiedAcceptance}/>Permit acceptance with recorded exceptions</label><label>Required crew skills (comma separated)<input value={profile.requiredSkills.join(', ')} oninput={e=>profile.requiredSkills=e.currentTarget.value.split(',').map(s=>s.trim()).filter(Boolean)}/></label><details><summary>Trade fields & status labels</summary>{#each Object.entries(profile.fields) as [key,label]}<label>{label}<input value={label} oninput={e=>profile.fields[key]=e.currentTarget.value}/></label><label class="check"><input type="checkbox" checked={profile.requiredFields.includes(key)} onchange={e=>profile.requiredFields=e.currentTarget.checked?[...profile.requiredFields,key]:profile.requiredFields.filter(k=>k!==key)}/>Required for readiness</label>{/each}<label>New trade field<input bind:value={fieldLabel}/></label><button type="button" onclick={()=>{const key=fieldLabel.toLowerCase().replace(/[^a-z0-9]+/g,'-');if(key)profile.fields[key]=fieldLabel;fieldLabel='';}}>Add field</button>{#each ['DRAFT','PLANNING','BLOCKED','READY_TO_SCHEDULE','SCHEDULED','READY_TO_START','IN_PROGRESS','PAUSED','WAITING','READY_FOR_COMPLETION','COMPLETION_REVIEW','COMPLETED','CLOSED','CANCELLED'] as state}<label>{state.replaceAll('_',' ')}<input value={profile.stateLabels[state]||''} placeholder="Default label" oninput={e=>{if(e.currentTarget.value)profile.stateLabels[state]=e.currentTarget.value;else delete profile.stateLabels[state];}}/></label>{/each}</details><h2>Checklist template</h2>{#each profile.tasks as task,i}<div class="task"><label>Task {i+1}<input bind:value={task.title} required/></label><label>Required before<select bind:value={task.stage}><option value="schedule">Scheduling</option><option value="start">Starting</option><option value="complete">Completion</option></select></label><label class="check"><input type="checkbox" bind:checked={task.required}/>Required</label><label class="check"><input type="checkbox" bind:checked={task.evidenceRequired}/>Evidence required</label><button type="button" onclick={()=>profile.tasks.splice(i,1)}>Remove task {i+1}</button></div>{/each}<button type="button" onclick={()=>profile.tasks.push({title:'',stage:'complete',required:true,evidenceRequired:false})}>Add task</button>
 {:else}<p>Using the platform trade defaults. Customizing replaces those defaults for new Jobs.</p><button type="button" disabled={!ready} onclick={customize}>Customize this trade profile</button>{/if}
 <details><summary>Bob action authority</summary><p>Permissions and readiness checks still apply. Automatic actions execute only when explicitly requested or invoked by an authorized workflow.</p>{#each ['job.summarize','job.readiness','job.structure','job.recommend','job.schedule','job.task','job.change','job.material','job.activity','job.transition','job.notify'] as action}<label>{action.replace('job.','').replace('notify','Notify customer')}<select value={policy.aiActions?.[action]||(['job.summarize','job.readiness','job.structure','job.recommend'].includes(action)?'read':'approval')} onchange={e=>{policy.aiActions??={};policy.aiActions[action]=e.currentTarget.value;}}>{#each ['disabled','read','recommend','draft','approval','auto'] as mode}<option value={mode}>{mode==='auto'?'Automatic by policy':mode==='approval'?'Human approval':mode}</option>{/each}</select></label>{/each}</details>
 <details><summary>People skills</summary>{#each data.choices.members as member}<label>{member.name}<input value={(policy.memberSkills[member.id]??[]).join(', ')} oninput={e=>policy.memberSkills[member.id]=e.currentTarget.value.split(',').map(s=>s.trim()).filter(Boolean)} placeholder="Confirmed skills, separated by commas"/></label>{/each}</details>
 <details><summary>Customer notifications & preferences</summary>{#each ['scheduled','arriving','rescheduled','information-needed','change-approval','completed','acceptance-request'] as key}<label>{key}<textarea value={policy.notificationTemplates[key]||''} oninput={e=>policy.notificationTemplates[key]=e.currentTarget.value} placeholder={"Use {job}, {site} and {state}"}></textarea></label>{/each}{#each data.choices.customers as c}<fieldset><legend>{c.name} · Confirmed communication preferences</legend>{#each ['email','sms'] as channel}<label class="check"><input type="checkbox" checked={(policy.customerChannels[c.id]??[]).includes(channel)} onchange={e=>{const prior=policy.customerChannels[c.id]??[];policy.customerChannels[c.id]=e.currentTarget.checked?[...prior,channel]:prior.filter(x=>x!==channel);}}/>{channel}</label>{/each}</fieldset>{/each}</details><button class="btn-primary">Save Job rules</button></form></section>
<style>.settings{color:var(--text-strong)}h1{font-size:1.8rem;font-weight:650}h2{font-size:1.2rem;font-weight:600}label{display:block;margin:.7rem 0}input:not([type=checkbox]):not([type=hidden]),select,textarea{display:block;width:100%;padding:.7rem;min-height:44px;background:var(--surface);border:1px solid var(--border-strong);color:var(--text-strong);border-radius:.4rem}.check{display:flex;align-items:center;gap:.7rem;min-height:44px}button,summary,a{min-height:44px;padding:.5rem;display:inline-block}summary{display:list-item;cursor:pointer}.task{border-top:1px solid var(--border);padding:1rem 0}:is(input,select,textarea,button,a,summary):focus-visible{outline:3px solid var(--teal-text);outline-offset:3px}</style>
